verifier_source:
# Standalone Python 3 verifier. No imports, no I/O, no floats.
# Entry point: verify(witness) -- raises on any failed check; returns True on PASS.
# Instance: A = perfect squares <= 100, N = 100, lower-bound exponent = 1/4.

def verify(witness):
    # fail-closed structural checks
    for key in ('A', 'N', 'lb_num', 'lb_den'):
        if key not in witness:
            raise ValueError('missing field ' + key)
    A = witness['A']
    N = witness['N']
    ln = witness['lb_num']
    ld = witness['lb_den']
    if not isinstance(N, int) or isinstance(N, bool) or N < 1:
        raise ValueError('N must be a positive integer')
    if not isinstance(ln, int) or isinstance(ln, bool) or ln < 0:
        raise ValueError('lb_num must be a nonnegative integer')
    if not isinstance(ld, int) or isinstance(ld, bool) or ld < 1:
        raise ValueError('lb_den must be a positive integer')
    if not isinstance(A, list) or len(A) == 0:
        raise ValueError('A must be a nonempty list')
    prev = 0
    for a in A:
        if not isinstance(a, int) or isinstance(a, bool):
            raise ValueError('non-integer element of A')
        if a <= 0:
            raise ValueError('non-positive element of A')
        if a <= prev:
            raise ValueError('A not strictly increasing')
        prev = a
    # exact r_A(n) in Z-arithmetic, unordered pairs a <= b, capped at 2
    bad = 0
    As = set(A)
    for n in range(1, N + 1):
        r = 0
        for a in A:
            if a > n:
                break
            b = n - a
            if b in As and a <= b:
                r += 1
                if r >= 2:
                    break
        if r != 1:
            bad += 1
    # exact integer check bad >= N^(ln/ld):  bad**ld >= N**ln
    if not (bad ** ld >= N ** ln):
        raise ValueError('lower bound violated: bad=' + str(bad))
    return True

WITNESS = {'A': [1, 4, 9, 16, 25, 36, 49, 64, 81, 100], 'N': 100, 'lb_num': 1, 'lb_den': 4}
verify(WITNESS)
